import{_ as l,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Multi Cluster Ceph at Scale - Vasyl Purchel, Workday","description":"","frontmatter":{"title":"Multi Cluster Ceph at Scale - Vasyl Purchel, Workday","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","持续交付","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Multi_Cluster_Ceph_at_Scale_-_Vasyl_Purchel_Workday.md","filePath":"posts/2023/Multi_Cluster_Ceph_at_Scale_-_Vasyl_Purchel_Workday.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Multi_Cluster_Ceph_at_Scale_-_Vasyl_Purchel_Workday.md"};function o(s,a,h,n,_,u){return e(),t("div",null,[...a[0]||(a[0]=[r('<p>Workday的高级软件工程师Vasil在会议中分享了他们在数据中心应用Ceph分布式存储的经验。以下是会议的主要内容：</p><h3 id="参与者与公司背景" tabindex="-1">参与者与公司背景 <a class="header-anchor" href="#参与者与公司背景" aria-label="Permalink to &quot;参与者与公司背景&quot;">​</a></h3><ul><li><strong>Vasil</strong> 是Workday的高级软件工程师，负责存储平台团队，专注于OSF解决方案。</li><li>Workday是一家专注于财务和人力资源领域的云端企业解决方案提供商。</li></ul><h3 id="团队与数据中心概况" tabindex="-1">团队与数据中心概况 <a class="header-anchor" href="#团队与数据中心概况" aria-label="Permalink to &quot;团队与数据中心概况&quot;">​</a></h3><ul><li>团队由五名工程师和一名Red Hat顾问组成。</li><li>管理五个数据中心，拥有23个集群，超过1200台服务器，近100PB的存储容量。</li></ul><h3 id="主要挑战与解决方案" tabindex="-1">主要挑战与解决方案 <a class="header-anchor" href="#主要挑战与解决方案" aria-label="Permalink to &quot;主要挑战与解决方案&quot;">​</a></h3><ul><li><strong>数据存储与恢复</strong>：从NFS迁移到Ceph存储，显著缩短了MySQL备份时间。</li><li><strong>集群管理</strong>：实施多集群策略，分离性能和存储集群，减少故障影响范围。</li><li><strong>技术支持与监控</strong>：利用Red Hat商业支持和统一监控系统，提高故障诊断效率。</li></ul><h3 id="技术细节" tabindex="-1">技术细节 <a class="header-anchor" href="#技术细节" aria-label="Permalink to &quot;技术细节&quot;">​</a></h3><ul><li><strong>集群配置</strong>：标准集群使用三副本策略，高密度集群使用擦除编码技术。</li><li><strong>自动化与持续交付</strong>：实施自动化工具，确保集群变更的安全性和有效性。</li></ul><h3 id="未来规划与挑战" tabindex="-1">未来规划与挑战 <a class="header-anchor" href="#未来规划与挑战" aria-label="Permalink to &quot;未来规划与挑战&quot;">​</a></h3><ul><li><strong>升级与维护</strong>：计划从Ceph 4升级到Ceph 5（Pacific）。</li><li><strong>跨站点复制</strong>：探索Ceph的跨站点复制功能，实现灾难恢复。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>Vasil强调了自动化、社区贡献和持续改进的重要性，并提出了面临的挑战和未来的发展方向。</p><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>推进Ceph版本的升级。</li><li>加强自动化和监控系统的建设。</li><li>探索和实施跨站点复制的解决方案。</li></ul>',15)])])}const p=l(i,[["render",o]]);export{c as __pageData,p as default};
